{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "상담사가 '내가 원래 없는 사람'이라는 자기 인식에서 '자동인 줄도 모르고'라는 패턴 인식으로의 전환을 짚으며, 지금 이렇게 보는 기분을 질문함. 이는 융합/미발달 자기 스키마(융합 없이는 공허감을 경험하는 구조)와 직접 연결됨. /childhood_data는 그 공허감이 어머니의 결정 독점으로 인해 자기 선택 경험이 누적되지 못한 데서 기원함을 설명하고, /situations/3는 약혼자의 질문에 '나는 껍데기뿐인가'라는 생각으로 공허감이 현실화된 사례임."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '내가 원래 없는 사람인 줄만 아셨을 텐데'라고 과거 자기 인식을 요약한 것은 '엄마와 떨어진 나는 누구인지 모르겠고, 내 판단만으로 결정된 삶은 상상이 되지 않는다'는 핵심신념과 정확히 대응함. /childhood_data는 이 신념이 어머니의 서운한 얼굴을 피하기 위해 자기 판단 전에 어머니의 반응을 먼저 확인하는 자동화가 반복된 결과임을 보여줌."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '자동'이라고 알아차리는 지금과, 예전에는 '원래 없는 사람'으로만 알았던 과거를 대비시키며 스키마의 작동 방식을 의식화하고 있음. /childhood_data는 개별화된 정체성·방향성이 발달하지 못한 채 어머니의 판단이 곧 자신의 판단이 된 채 성인이 된 과정을 구체적으로 서술하여, 융합 없이는 공허감을 경험하는 구조의 기원을 설명함."
    }
  ]
}

